const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions (approximate area around Bay Dosgris, south of New Orleans)
    const roi = ee.Geometry.Polygon([
      [-90.20, 29.15],
      [-90.20, 29.50],
      [-89.50, 29.50],
      [-89.50, 29.15]
    ]);

    // Helpers
    function prepLandsatL2(image) {
      const qa = image.select('QA_PIXEL');
      const mask = qa.bitwiseAnd(1 << 1).eq(0) // dilated cloud
        .and(qa.bitwiseAnd(1 << 2).eq(0))     // cirrus
        .and(qa.bitwiseAnd(1 << 3).eq(0))     // cloud
        .and(qa.bitwiseAnd(1 << 4).eq(0))     // cloud shadow
        .and(qa.bitwiseAnd(1 << 5).eq(0));    // snow
      const isL57 = image.bandNames().contains('SR_B1');
      const renamed = ee.Image(ee.Algorithms.If(
        isL57,
        image.select(['SR_B1','SR_B2','SR_B3','SR_B4','SR_B5','SR_B7'],
                     ['blue','green','red','nir','swir1','swir2']),
        image.select(['SR_B2','SR_B3','SR_B4','SR_B5','SR_B6','SR_B7'],
                     ['blue','green','red','nir','swir1','swir2'])
      ));
      const scaled = renamed.multiply(0.0000275).add(-0.2).updateMask(mask);
      return scaled.copyProperties(image, image.propertyNames());
    }

    function buildCollection(year, mStart, mEnd) {
      const start = ee.Date.fromYMD(year, mStart, 1);
      const end = ee.Date.fromYMD(year, mEnd, 1).advance(1, 'month');
      const lt05 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2');
      const le07 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2'); // fallback if needed (not for 2024)
      const lc08 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2');
      const lc09 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2');
      return lt05.merge(le07).merge(lc08).merge(lc09)
        .filterBounds(roi)
        .filterDate(start, end);
    }

    async function analyzeYear(year) {
      // Primary window Jun–Sep
      let col = buildCollection(year, 6, 9);
      let size = await col.size().getInfo();
      if (size === 0) {
        // Fallback Apr–Nov
        col = buildCollection(year, 4, 11);
        size = await col.size().getInfo();
        if (size === 0) {
          return {status: 'C1', msg: `No images for ${year}`};
        }
      }
      const prepped = col.map(prepLandsatL2);
      const composite = prepped.median().clip(roi);

      // Valid pixel counts at 1000 m
      const totalPix = ee.Image.constant(1).rename('one')
        .reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: roi, scale: 1000, maxPixels: 1e9
        }).get('one');
      const validPix = composite.select('green')
        .reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: roi, scale: 1000, maxPixels: 1e9
        }).get('green');

      const areaImg = ee.Image.pixelArea().divide(1e6).rename('area'); // km2

      const mndwi = composite.expression(
        '(g - s) / (g + s)', {g: composite.select('green'), s: composite.select('swir1')}
      );
      const ndvi = composite.normalizedDifference(['nir', 'red']);

      const waterMask = mndwi.gt(0.1);
      const wetlandMask = ndvi.gt(0.3).and(waterMask.not());

      const waterArea = areaImg.updateMask(waterMask).reduceRegion({
        reducer: ee.Reducer.sum(), geometry: roi, scale: 1000, maxPixels: 1e9
      }).get('area');
      const wetlandArea = areaImg.updateMask(wetlandMask).reduceRegion({
        reducer: ee.Reducer.sum(), geometry: roi, scale: 1000, maxPixels: 1e9
      }).get('area');

      const dict = ee.Dictionary({
        images: col.size(),
        totalPix: totalPix,
        validPix: validPix,
        validFrac: ee.Number(validPix).divide(ee.Number(totalPix)),
        water_km2: waterArea,
        wetland_km2: wetlandArea
      });

      const out = await dict.getInfo();
      // Validations
      if (out.validPix === 0 || out.validPix === null) {
        return {status: 'C2', msg: `No valid pixels for ${year}`};
      }
      const w = out.water_km2;
      const wl = out.wetland_km2;
      if (w === null || wl === null || !isFinite(w) || !isFinite(wl) || wl === 0) {
        return {status: 'C3', msg: `Invalid computation for ${year}`};
      }
      const ratio = w / wl;
      if (!isFinite(ratio)) {
        return {status: 'C3', msg: `Invalid ratio for ${year}`};
      }
      return {
        status: 'OK',
        year: year,
        images: out.images,
        totalPix: out.totalPix,
        validPix: out.validPix,
        validFrac: out.validFrac,
        water_km2: w,
        wetland_km2: wl,
        ratio: ratio
      };
    }

    // 1985 and 2024 analyses
    const y1 = await analyzeYear(1985);
    const y2 = await analyzeYear(2024);

    if (y1.status !== 'OK' || y2.status !== 'OK') {
      // Propagate the first encountered issue code
      const code = y1.status !== 'OK' ? y1.status : y2.status;
      console.log(`1985 Images: ${y1.images || 0} ${y1.validFrac ? `(Valid: ${(y1.validFrac*100).toFixed(1)}%)` : ''}`);
      console.log(`2024 Images: ${y2.images || 0} ${y2.validFrac ? `(Valid: ${(y2.validFrac*100).toFixed(1)}%)` : ''}`);
      console.log(code);
      return;
    }

    // Print concise evidence
    const v1pct = (y1.validFrac * 100).toFixed(1);
    const v2pct = (y2.validFrac * 100).toFixed(1);
    console.log(`1985 Images: ${y1.images}, Valid km-px: ${y1.validPix}/${y1.totalPix} (${v1pct}%)`);
    console.log(`1985 Water km2: ${y1.water_km2.toFixed(1)}, Wetland km2: ${y1.wetland_km2.toFixed(1)}, Ratio W/Wet: ${y1.ratio.toFixed(2)}`);
    console.log(`2024 Images: ${y2.images}, Valid km-px: ${y2.validPix}/${y2.totalPix} (${v2pct}%)`);
    console.log(`2024 Water km2: ${y2.water_km2.toFixed(1)}, Wetland km2: ${y2.wetland_km2.toFixed(1)}, Ratio W/Wet: ${y2.ratio.toFixed(2)}`);
    const delta = y2.ratio - y1.ratio;
    console.log(`Δ Ratio (2024-1985): ${delta.toFixed(2)}`);

    // Final decision
    const answer = delta > 0 ? 'A' : 'B';
    console.log(answer);
  } catch (e) {
    // Any coding/data/memory error
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
